from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, computed in
    parallel with a thread pool. Results are in input order, regardless
    of worker count or completion order."""
    with ThreadPoolExecutor() as ex:
        return list(ex.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2, -3]) == [1, 0, 1]


def test_parities_zero_and_large() -> None:
    assert parities([0, 10**30, 10**30 + 1]) == [0, 0, 1]


def test_parities_order_preserved_large() -> None:
    xs = list(range(1000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_order_independent_of_completion_time() -> None:
    import random
    import time

    rng = random.Random(0)
    xs = [rng.randrange(-100, 100) for _ in range(200)]
    delays = {i: rng.random() * 0.002 for i in range(len(xs))}

    def slow_parity(i: int) -> int:
        time.sleep(delays[i])
        return parity(xs[i])

    with ThreadPoolExecutor(max_workers=8) as ex:
        slow = list(ex.map(slow_parity, range(len(xs))))
    assert parities(xs) == slow


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 6, 7]
    copy = list(xs)
    parities(xs)
    assert xs == copy


def test_parities_returns_new_list() -> None:
    xs = [1, 2]
    assert parities(xs) is not xs

